// Guardarraíl de gasto. La cuenta es plan STARTER con tope duro de 19 $/mes:
// si se agota, Apify corta los runs a mitad de mes y el captador se queda mudo.
// Aquí se para el captador cuando el gasto toca el disponible (límite - reserva).
const LIMITE_CUENTA = 19;
const RESERVA = 2;            // colchón intocable para el resto del mes
const DISPONIBLE = LIMITE_CUENTA - RESERVA;

const raw = $input.first().json;
const uso = raw.data || raw;

// El freno tiene que fallar CERRADO. El nodo de arriba lleva
// onError:continueRegularOutput, asi que si la API de Apify da un 429, un 5xx o
// se pasa del timeout, igualmente emite un item, y el item no trae el campo del
// gasto. Con `Number(undefined || 0)` eso se convertia en 'has gastado 0 euros',
// que es la lectura MAS PERMISIVA posible justo cuando se ha perdido la unica
// medida real. Ademas escribia ese 0 en app_settings y el medidor del CRM se
// ponia a cero mientras se seguia gastando. Ocurrio de verdad: ejecucion 56160
// del 08/09 a las 16:00.
const bruto = uso.totalUsageCreditsUsdBeforeVolumeDiscount;
const lecturaOk = !raw.error && bruto != null && isFinite(Number(bruto));
if (!lecturaOk) {
  return [{
    json: {
      lectura_ok: false,
      seguir: false,
      motivo: 'no se pudo leer el gasto de Apify',
      detalle: String((raw.error && (raw.error.message || raw.error)) || 'la respuesta no traia el consumo').slice(0, 200),
      actualizado: new Date().toISOString(),
    },
  }];
}
const gastado = Number(bruto);

const ciclo = uso.usageCycle || {};
const ini = new Date(ciclo.startAt || Date.now()).getTime();
const fin = new Date(ciclo.endAt || Date.now() + 2592000000).getTime();
const ahora = Date.now();
const progreso = Math.min(Math.max((ahora - ini) / Math.max(fin - ini, 1), 0), 1);

// Aqui habia un segundo freno "por ritmo": repartia el presupuesto a partes
// iguales por el ciclo y saltaba pasadas si el gasto iba por delante. Se quito el
// 17/09/2026: el gasto gordo fue la primera semana (barridos completos) y desde
// que el actor va en monitoringMode cada pasada cuesta ~0,008 $, unos 0,22 $/dia.
// El freno se quedaba dias parado cobrando una deuda que ya no se va a repetir.
// Queda SOLO el tope duro, que es el que protege de verdad la cuenta.
const agotado = gastado >= DISPONIBLE;

// Cuanto queda de margen real, para que el panel del CRM pueda avisar antes de
// que el freno muerda en vez de despues.
const restante = Math.max(0, DISPONIBLE - gastado);
const diasRestantes = Math.max(1, Math.ceil((fin - ahora) / 86400000));

return [{
  json: {
    lectura_ok: true,
    gastado: Math.round(gastado * 1000) / 1000,
    limite: LIMITE_CUENTA,
    disponible: DISPONIBLE,
    progreso_ciclo: Math.round(progreso * 100),
    ciclo_fin: ciclo.endAt || null,
    restante: Math.round(restante * 100) / 100,
    dias_restantes: diasRestantes,
    por_dia_restante: Math.round(restante / diasRestantes * 100) / 100,
    seguir: !agotado,
    motivo: agotado ? 'presupuesto agotado' : 'ok',
    actualizado: new Date().toISOString(),
  },
}];

const todas = $input.all().map(function (i) { return i.json; }).filter(function (z) { return z && z.url; });
if (!todas.length) {
  throw new Error('No hay ninguna zona activa. Ve a Captaciones -> Configuracion del captador y activa al menos una.');
}

// Dos modos, distinguidos por el cron que ha disparado la ejecucion:
//  - rapido (cada 30 min): monitoringMode ON. Solo emite lo que no ha emitido antes.
//  - red de seguridad (07:00): monitoringMode OFF. Reemite todo lo de la ventana y
//    Supabase deduplica. Cubre el punto debil de monitoringMode: si una ingesta
//    falla, ese anuncio no vuelve a emitirse jamas.
const esRed = $('Red de Seguridad (07:00)').isExecuted;

// ventana_horas = 0 significa BARRIDO: sin filtro de fecha, ordenado de mas nuevo a
// mas viejo, dejando que monitoringMode descarte lo ya emitido. Asi cada pasada
// avanza hacia el fondo del catalogo en vez de mirar siempre las mismas 24h.
// Comprobado: dos pasadas seguidas devolvieron 40 anuncios cada una con CERO
// repetidos, y la segunda llegaba ya a 5 dias de antiguedad.
function esBarrido(z) { return Number(z.ventana_horas) === 0; }

// La red de seguridad NO puede tocar las zonas de barrido: sin ventana que la acote,
// reemitir 'todo' seria el catalogo entero de Valencia cada manana. Para esas zonas
// la repesca de un anuncio perdido tiene que venir por otro lado, no por fuerza bruta.
const zonas = esRed ? todas.filter(function (z) { return !esBarrido(z); }) : todas;
if (!zonas.length) {
  return [{ json: { modo: 'red-de-seguridad', zonas: 0, detalle: 'ninguna zona con ventana: la red de seguridad no aplica a las de barrido', saltar: true } }];
}

// La ventana de publicacion es una propiedad DE CADA ZONA, no una constante.
// Vivienda en Valencia mueve ~375 anuncios en 48h y con 24h ya va sobrada; los
// locales mueven 13 en 48h y con 24h no sale ni uno. Una sola cifra global deja
// fuera a los mercados finos o dispara el gasto en los gruesos.
function conVentana(url, horas) {
  const token = 'publicado_ultimas-' + horas + '-horas';

  // Con segmento /con-.../: se sustituye la ventana y se respetan los demas
  // filtros que traiga la URL (precio, habitaciones, etc.).
  if (/\/con-/.test(url)) {
    return url.replace(/\/con-([^/?]*)/, function (_m, filtros) {
      const lista = String(filtros)
        .split(',')
        .filter(Boolean)
        .filter(function (f) { return f.indexOf('publicado_') !== 0; });
      lista.unshift(token);
      return '/con-' + lista.join(',');
    });
  }

  // Sin segmento /con-.../: se INYECTA. Antes se devolvia la URL intacta, y una
  // zona sin ventana pide todo el historico en cada pasada: en locales de Valencia
  // son miles de filas cada 30 minutos, y la red de seguridad las recobraria
  // enteras cada dia. Es la diferencia entre gastar centimos y fundir el mes.
  const i = url.indexOf('?');
  const camino = i === -1 ? url : url.slice(0, i);
  const cola = i === -1 ? '' : url.slice(i);
  return camino.replace(/\/?$/, '/') + 'con-' + token + '/' + cola;
}

// TODAS las zonas activas van en un unico run: el arranque del actor ($0.007) se
// paga una sola vez en lugar de una por zona. Cada URL lleva su propia ventana,
// asi que mezclar vivienda a 24h y locales a 48h en la misma pasada es gratis.
//
// Si la zona no tiene ventana propia (fila creada antes de la migracion 004) se
// respeta la que ya trae su URL en vez de imponerle 24h. Sin esto, una zona de
// locales guardada a 48h se reescribiria a 24h y no captaria absolutamente nada,
// y encima el sintoma seria "no encuentra anuncios" y no "falta el SQL".
function ventanaDeLaUrl(url) {
  const m = /publicado_ultimas-(\d+)-horas/.exec(String(url));
  return m ? Number(m[1]) : 0;
}

// Quita el filtro de fecha y, si la URL no dice otra cosa, ordena por publicacion
// descendente: asi un anuncio publicado hoy sale en la siguiente pasada en vez de
// esperar a que el barrido llegue hasta el.
//
// Pero si la zona YA trae un ordenado-por, se respeta. Es lo que permite tener una
// zona de nuevos (desc, por defecto) y otra de rezagados (asc), que recorre el
// catalogo desde el fondo. Probado: con asc la mediana de antiguedad sube a 71
// dias y los particulares pasan del 7% al 13%.
function sinVentana(url) {
  let u = String(url);
  if (/\/con-/.test(u)) {
    u = u.replace(/\/con-([^/?]*)/, function (_m, filtros) {
      const lista = String(filtros).split(',').filter(Boolean)
        .filter(function (f) { return f.indexOf('publicado_') !== 0; });
      // Si la zona no tenia mas filtros que la ventana, el segmento entero sobra.
      return lista.length ? '/con-' + lista.join(',') : '';
    });
  }
  const i = u.indexOf('?');
  const camino = i === -1 ? u : u.slice(0, i);
  const cola = i === -1 ? '' : u.slice(i + 1);
  const params = cola.split('&').filter(Boolean);
  const yaOrdena = params.some(function (p) { return p.indexOf('ordenado-por=') === 0; });
  if (!yaOrdena) params.push('ordenado-por=fecha-publicacion-desc');
  return camino.replace(/\/?$/, '/') + '?' + params.join('&');
}

function urlDeZona(z) {
  if (esBarrido(z)) return sinVentana(z.url);
  const horas = Number(z.ventana_horas) > 0 ? Number(z.ventana_horas)
    : (ventanaDeLaUrl(z.url) || 24);
  return conVentana(z.url, horas);
}

// ---- REPARTO DE PASADAS POR PRIORIDAD ----
// Antes las zonas viajaban todas juntas con un tope de anuncios COMPARTIDO: la
// grande se comia el cupo y la pequena se truncaba en silencio, y encima no habia
// forma de saber que habia aportado cada una.
//
// Ahora cada pasada rapida lleva UNA zona. El arranque del actor cuesta lo mismo
// (se paga uno por pasada de todas formas), el tope entero es para ella, y el
// recuento por zona pasa a ser exacto en vez de deducido por tipo de inmueble.
//
// El turno se decide por prioridad: la primera zona se lleva el doble de pasadas
// que la segunda, esta el doble que la tercera, y asi. Ninguna se queda a cero,
// que es lo que pasaria con un orden estricto: mientras se barre el fondo del
// catalogo se dejaria de captar lo recien publicado, que es lo que mas convierte.
//
// El turno sale del reloj y no de un contador guardado: asi no hay estado que
// mantener ni que se desincronice si n8n reinicia.
const ordenadas = zonas.slice().sort(function (a, b) {
  const pa = Number(a.prioridad != null ? a.prioridad : 100);
  const pb = Number(b.prioridad != null ? b.prioridad : 100);
  if (pa !== pb) return pa - pb;
  return String(a.nombre || '').localeCompare(String(b.nombre || ''));
});

let elegidas;
if (esRed || ordenadas.length === 1) {
  // La red de seguridad corre una vez al dia: se le dan todas de golpe.
  elegidas = ordenadas;
} else {
  const ranura = [];
  ordenadas.forEach(function (z, i) {
    const peso = Math.max(1, Math.pow(2, ordenadas.length - 1 - i));
    for (let k = 0; k < peso; k++) ranura.push(z);
  });
  const d = new Date();
  const turno = Math.floor((d.getUTCHours() * 60 + d.getUTCMinutes()) / 30);
  elegidas = [ranura[turno % ranura.length]];
}

const urls = elegidas.map(function (z) { return { url: urlDeZona(z) }; });

return [{
  json: {
    modo: esRed ? 'red-de-seguridad' : 'rapido',
    zonas: elegidas.length,
    // Los ids de las zonas que van en ESTA pasada. Con una sola zona por pasada,
    // el reparto de resultados deja de ser una deduccion por tipo de inmueble y
    // pasa a ser un hecho.
    zona_ids: elegidas.map(function (z) { return z.id; }),
    turno_de: elegidas.map(function (z) { return z.nombre; }).join(' · '),
    detalle: elegidas.map(function (z) {
      const v = Number(z.ventana_horas) === 0 ? 'barrido' : (z.ventana_horas || 24) + 'h';
      return z.nombre + ' (' + (z.operacion || 'venta') + '/' + (z.tipo_inmueble || 'viviendas') + ', ' + v + ')';
    }).join(' · '),
    en_cola: ordenadas.map(function (z, i) {
      return (i + 1) + '. ' + z.nombre;
    }).join(' | '),
    apify_input: {
      startUrls: urls,
      maxItems: esRed ? 400 : 150,
      maxConcurrency: 8,
      minConcurrency: 1,
      monitoringMode: !esRed,
    },
  },
}];

// Rutas reales del actor memo23/idealista-scraper (build 0.0.164).
// Casi todo lo util vive bajo moreCharacteristics, NO en la raiz del item.
const ESTADO_LEGIBLE = { good: 'Buen estado', renew: 'A reformar', newdevelopment: 'Obra nueva' };

// Idealista devuelve el telefono en varios formatos segun el anuncio. Se normaliza
// a 34XXXXXXXXX y se descarta lo que no sea un movil/fijo espanol valido, para que
// ni Evolution ni el CRM reciban basura.
function telefonoES(contacto) {
  const p = (contacto && contacto.phone1) || {};
  const num = String(p.phoneNumber == null ? '' : p.phoneNumber).replace(/\D/g, '');
  const pref = String(p.prefix == null ? '' : p.prefix).replace(/\D/g, '');
  let d = num ? (pref || '34') + num : '';
  if (!d) {
    d = String(p.formattedPhoneWithPrefix || p.formattedPhone || '').replace(/\D/g, '');
    if (d.startsWith('00')) d = d.slice(2);
    if (d.length === 9) d = '34' + d;
  }
  return /^34[6-9]\d{8}$/.test(d) ? d : null;
}

// Idealista da el barrio en ingles y con prefijo: "Subdistrict El Pilar",
// "District Camins al Grau". Se guarda limpio para que no salga asi en ninguna
// pantalla ni en ningun mensaje. Mismo patron que "Analizar Inmueble" (wf 4):
// espacio literal y no barra-s, porque las barras se perdian al generar el codigo.
function sinPrefijo(b) {
  const t = String(b == null ? '' : b).replace(/^(sub)?district +/i, '').trim();
  return t || null;
}

const salida = [];

for (const item of $input.all()) {
  const e = item.json || {};
  const ci = e.contactInfo || {};

  // Solo particulares: una agencia no es una captacion.
  if (ci.userType !== 'private' || ci.professional === true) continue;
  if (e.state && e.state !== 'active') continue;
  if (!e.adid) continue;

  const mc = e.moreCharacteristics || {};
  const bi = e.basicInfo || {};
  const ub = e.ubication || {};

  const metros = mc.constructedArea != null ? mc.constructedArea
    : (bi.constructedArea != null ? bi.constructedArea : null);
  const precio = e.price != null ? e.price
    : (e.priceInfo && e.priceInfo.amount != null ? e.priceInfo.amount : null);
  const estadoRaw = mc.status || bi.status || null;
  const planta = mc.floor != null ? mc.floor : (bi.floor != null ? bi.floor : null);
  const ascensor = mc.lift != null ? mc.lift
    : (mc.hasLift != null ? mc.hasLift : (bi.hasLift != null ? bi.hasLift : null));

  // raw_data sin las descripciones multi-idioma: cuadruplican el peso y no se usan.
  const rawSlim = Object.assign({}, e);
  delete rawSlim.comments;
  delete rawSlim.translatedTexts;

  // Solo la PRIMERA. El CRM pinta imagenes[0] en los cuatro sitios donde sale una
  // foto y no hay galeria en ninguno. Se guardaban 7,1 de media por captacion:
  // el 86% se descargaba, se convertia a WebP y se subia a Storage para nada.
  const fotos = ((e.multimedia && e.multimedia.images) || [])
    .map(function (img) { return img && img.url; })
    .filter(Boolean)
    .slice(0, 1);

  const telefono = telefonoES(ci);

  salida.push({
    json: {
      // captacion coincide 1:1 con las columnas de public.captaciones
      captacion: {
        id: Number(e.adid),
        nombre: ci.contactName || 'Propietario',
        telefono: telefono,
        precio: precio,
        precio_m2: e.priceByArea != null ? e.priceByArea
          : (precio && metros ? Math.round(precio / metros) : null),
        barrio: sinPrefijo(ub.administrativeAreaLevel4 || ub.administrativeAreaLevel3),
        calle: ub.title || null,
        metros: metros,
        habitaciones: mc.roomNumber != null ? mc.roomNumber
          : (bi.roomNumber != null ? bi.roomNumber : null),
        banos: mc.bathNumber != null ? mc.bathNumber
          : (bi.bathNumber != null ? bi.bathNumber : null),
        planta: planta == null ? null : String(planta),
        tiene_ascensor: typeof ascensor === 'boolean' ? ascensor : null,
        estado: estadoRaw ? (ESTADO_LEGIBLE[estadoRaw] || estadoRaw) : null,
        descripcion: e.propertyComment || null,
        url: e.detailWebLink || null,
        // Sin telefono no hay captacion posible: el propietario ha elegido en
        // Idealista que solo se le escriba por el chat de la plataforma
        // (contactMethod 'email'). Se guarda igual, porque se le puede contactar
        // a mano por ahi, pero marcado para que no ocupe sitio en la cola: esa
        // consulta pide estado_whatsapp IS NULL. Son el 45% de lo que trae el
        // barrido, asi que dejarlos entrar tapaba a los que si tienen numero.
        // Sin numero no hay a quien escribir, asi que se guarda marcada y no
        // entra en la cola: su consulta pide estado_whatsapp IS NULL. Se guarda
        // igualmente porque a esos propietarios se les puede escribir a mano por
        // el chat de Idealista, y porque monitoringMode no vuelve a emitir el
        // anuncio nunca mas: si se descartara aqui, se perderia para siempre.
        estado_whatsapp: telefono ? null : 'Sin_Telefono',
        contacto_lock_en: null,
        fotos_procesadas: false,
        raw_data: rawSlim,
      },
      fotos: fotos,
    },
  });
}

return salida;

// Marca en scraper_zonas que zona ha corrido y cuantos particulares saco.
//
// En la pasada rapida va UNA sola zona, asi que el recuento es un hecho y no una
// deduccion. La red de seguridad si lleva varias juntas, y ahi hay que repartir
// por tipo y operacion, que es lo unico que distingue un anuncio de otro cuando
// vienen mezclados en el mismo run.
const prep = $('Preparar Input Apify').first().json;
const idsEnEstaPasada = prep.zona_ids || [];
const zonas = $('Zonas Activas').all()
  .map(function (i) { return i.json; })
  .filter(function (z) { return idsEnEstaPasada.indexOf(z.id) !== -1; });

// Solo cuentan los particulares, que es lo que el panel llama 'N particulares'.
const captados = $('Normalizar Inmuebles').isExecuted
  ? $('Normalizar Inmuebles').all().map(function (i) { return (i.json && i.json.captacion && i.json.captacion.raw_data) || {}; })
  : [];

const cuando = new Date().toISOString();

// Caso normal de la pasada rapida: una zona, todo lo captado es suyo.
if (zonas.length === 1) {
  return [{ json: { zona_id: zonas[0].id, zona: zonas[0].nombre, ultima_ejecucion: cuando, ultimo_resultado: captados.length } }];
}

// Varias zonas en el mismo run (red de seguridad): se atribuye por tipo y operacion.
const TIPO = { homes: 'viviendas', rooms: 'viviendas', premises: 'locales', offices: 'oficinas', garages: 'garajes', lands: 'terrenos', storageRooms: 'trasteros' };
const OPERACION = { sale: 'venta', rent: 'alquiler' };
const salida = [];

for (const z of zonas) {
  const zTipo = z.tipo_inmueble || 'viviendas';
  const zOper = z.operacion || 'venta';
  const suyos = captados.filter(function (rd) {
    const t = TIPO[rd.propertyType] || 'viviendas';
    const o = OPERACION[rd.operation] || 'venta';
    return t === zTipo && o === zOper;
  });
  salida.push({ json: { zona_id: z.id, zona: z.nombre, ultima_ejecucion: cuando, ultimo_resultado: suyos.length } });
}

// Si dos zonas comparten tipo y operacion (por ejemplo 'nuevos' y 'rezagados',
// las dos venta/viviendas) los mismos anuncios se contarian en las dos. Se avisa
// en vez de dar por bueno un total que no cuadra.
const repartidos = salida.reduce(function (a, s) { return a + s.json.ultimo_resultado; }, 0);
if (repartidos !== captados.length && salida.length) {
  salida[0].json.aviso = 'repartidos ' + repartidos + ' de ' + captados.length + ' captados';
}

return salida;

// ============================================================
// CAP 01 · Recortar para mercado — nodo Code ("Run Once for All Items")
// Justo antes del POST al webhook de VAL 02 ("Guardar en mercado").
//
// POR QUÉ.
// Cada anuncio del actor pesa ~23 KB y más de la mitad son fotos: 13 KB en
// multimedia.images (URLs firmadas que caducan) y otros 3,4 KB repetidos en
// basicInfo.multimedia. VAL 02 sólo usa la URL de la primera foto (imagen_url) y
// cuántas hay (num_fotos). Recortado queda en 6,1 KB de media: un envío de 150
// anuncios pasa de ~3,3 MB a ~0,9 MB (medido sobre el rescate).
//
// DÓNDE VA. En una rama APARTE del flujo del captador: si no hay anuncios
// devuelve [] y, si estuviera en línea, pararía el resto de CAP 01.
//
// QUÉ QUITA.
//  - comments y translatedTexts (textos de más; el rescate ya venía sin ellos).
//  - multimedia: se queda SÓLO images, y de cada foto sólo multimediaId (la
//    primera, también url). Así images.length sigue siendo el número real de
//    fotos y el mapeo no necesita campos inventados. Los multimediaId se guardan
//    porque el conjunto de fotos es uno de los cambios reales que se quieren
//    detectar. Fuera videos, virtual3DTours y homestagings.
//  - basicInfo.multimedia (copia de las fotos), basicInfo.description (otro texto
//    distinto de propertyComment, traducido) y basicInfo.contactInfo (copia).
//  - contactInfo.phone1 y phone2: VAL 02 no los usa y así los teléfonos no
//    quedan también en el registro de ejecuciones de VAL 02.
//  - En los particulares (userType 'private' y no professional), también
//    contactInfo.contactName y profilePicture: son el nombre y la foto del
//    propietario (369 de los 3.925 rescatados). VAL 02 sólo lee contactName para
//    el nombre de la agencia, así que en un particular no lo usa nunca.
//  - Los items sin adid, como el {} vacío que sale en una pasada sin anuncios:
//    VAL 02 los tiraría igual, y así no se llama al webhook para nada.
//
// PROBADO el 17/09/2026 sobre los 3.925 anuncios rescatados: el mapeo de VAL 02
// da exactamente las mismas filas con el anuncio recortado que con el completo
// (t-mapeo.js). No toca los items de entrada: crea copias.
//
// SALIDA. UN item {anuncios:[...]}, que el HTTP Request manda tal cual con
// JSON.stringify($json). Sin anuncios devuelve [] y no se llama a VAL 02.
// Acepta también el formato del rescate {vista_en, anuncio}: recorta el anuncio y
// deja vista_en.
// ============================================================

function recortar(a) {
  if (!a || typeof a !== 'object') return a;
  const r = Object.assign({}, a);
  delete r.comments;
  delete r.translatedTexts;

  if (r.multimedia && typeof r.multimedia === 'object') {
    const imgs = Array.isArray(r.multimedia.images) ? r.multimedia.images : null;
    r.multimedia = imgs
      ? { images: imgs.map((im, i) => {
          const o = { multimediaId: im ? im.multimediaId : undefined };
          if (i === 0) o.url = im ? im.url : undefined;
          return o;
        }) }
      : {};
  }

  if (r.basicInfo && typeof r.basicInfo === 'object') {
    const bi = Object.assign({}, r.basicInfo);
    delete bi.multimedia;
    delete bi.description;
    delete bi.contactInfo;
    r.basicInfo = bi;
  }

  if (r.contactInfo && typeof r.contactInfo === 'object') {
    const ci = Object.assign({}, r.contactInfo);
    delete ci.phone1;
    delete ci.phone2;
    if (ci.userType === 'private' && ci.professional !== true) {
      delete ci.contactName;
      delete ci.profilePicture;
    }
    r.contactInfo = ci;
  }
  return r;
}

